WITH base AS (SELECT id, product_id, last_restock, DATE_FORMAT(last_restock, 'yyyy-MM') AS last_restock_label FROM inventory WHERE last_restock >= TO_DATE('2023-05-29') AND store_id IN (3, 6)) SELECT DATE_TRUNC('MONTH', last_restock) AS activity_month, product_id, COUNT(*) AS event_count, COUNT(DISTINCT product_id) AS distinct_product_ids FROM base GROUP BY DATE_TRUNC('MONTH', last_restock), product_id ORDER BY activity_month DESC;
